              <ul className="art:mt-10 art:space-y-4">
                {plan.features.map((feature, index) => <motion.li key={index} className={isDark ? "art:flex art:items-center art:gap-4 art:text-base art:@min-[640px]/artemis:text-lg art:text-white/64" : "art:flex art:items-center art:gap-4 art:text-base art:@min-[640px]/artemis:text-lg art:text-black/58"} initial={{ opacity: 0, x: -10 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.45, delay: reduced ? 0 : 0.18 + index * 0.055, ease: ARTEMIS_EASE_OUT, x: reduced ? { duration: 0 } : undefined }}>
                  <span className={isDark ? "art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:bg-white/8 art:text-white" : "art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:bg-black/6 art:text-black/72"}>
